    ctx.save();
    ctx.fillStyle = '#183136';
    ctx.fillRect(tower.x + 3, tower.y + 3, 10, 10);
    ctx.fillStyle = '#fff8dc';
    ctx.font = 'bold 8px monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
