      ctx.strokeRect(x - 7, y - 7, 14, 14);
      drawTower(ctx, { ...drag.source, x, y }, 0.65);
      drawLevel(ctx, { ...drag.source, x, y, level: drag.result === 'merge' ? drag.source.level + 1 : drag.source.level });
